MAX_IPERF_INTERVALS_DELAY = 30


class IphoneIperfDataTransfer(LteDataTransfer):
    """IphoneIperfDataTransfer class"""

    def __init__(self, name, ue_pc, iphone_name, dt_definition, configuration):
        """
        :param name: alias of data transfer
        :param ue_pc: Rpc object responsible for HTTP/HTTPS request
        :param iphone_name: id of iphone, e.g. 00008101-000144860011401E
        :param dt_definition: object containing data transfer's details
        :param configuration: UE configuration from config yaml file
        """
        super().__init__(name, dt_definition, configuration)
        self.supported_iperf_versions = [2, 3]
        self.dt_id = None
        self.iphone_name = iphone_name
        self.ue_pc = ue_pc
        self.is_dt_running = False

        self.dt_config = self._build_dt_config(dt_definition, configuration)
        self.moler_device = self._create_moler_device()
        self.port_for_dt()

        self.dt_id = "{}_{}_p{}".format(
            self.dt_config['direction'],
            self.dt_config['protocol'],
            self.dt_config['port'])

        self.iperf_cmd = None

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        iphone_iperf_cmd = self._build_iphone_iperf_command()
        command_name = "iperf" if self.dt_config['version'] == 2 else "iperf3"
        self.logger.info(f"iperf cmd (iphone): {command_name} {iphone_iperf_cmd}")
        appserver_iperf_cmd = self._build_app_server_iperf_command()
        self.logger.info(f"iperf cmd (app server): {command_name} {appserver_iperf_cmd}")
        self.iperf_cmd = self.moler_device.get_cmd(cmd_name=f"iperf{self.dt_config['version']}",
                                                   cmd_params={'options': appserver_iperf_cmd})
        data_transfer_class = "iphoneiperf" if self.dt_config['version'] == 2 else "iphoneiperf3"

        if self.dt_config["direction"] == "ul":
            self.iperf_cmd.start(timeout=self.dt_config["duration"] + 5)
            time.sleep(2)
            if self.iperf_cmd.done():
                raise IperfStartFailed(f"start cmd \"iperf {appserver_iperf_cmd}\" failed")
            self.ue_pc.start_data_transfer(ue_id=self.iphone_name,
                                           data_transfer_cmd=iphone_iperf_cmd,
                                           data_transfer_id=self.dt_id,
                                           data_transfer_class=data_transfer_class)
        elif self.dt_config["direction"] == "dl":
            self.ue_pc.start_data_transfer(ue_id=self.iphone_name,
                                           data_transfer_cmd=iphone_iperf_cmd,
                                           data_transfer_id=self.dt_id,
                                           data_transfer_class=data_transfer_class)
            time.sleep(2)
            self._verify_start_iperf_on_iphone()
            self.iperf_cmd.start(timeout=self.dt_config["duration"] + 3)
            if self.iperf_cmd.done():
                raise IperfStartFailed(f"start cmd \"iperf {appserver_iperf_cmd}\" failed")

    def stop(self):
        """
        Stops already running data transfer.
        :return: None
        """
        if not self.is_dt_running:
            self.logger.debug(f"{self.name}: data transfer was already stopped or finished. Skipping!")
            return
        if self.dt_config["direction"] == "dl":
            self._independently_stop_iperf_client_and_server(self._stop_iperf_appserver, self._stop_iperf_ue)
        elif self.dt_config["direction"] == "ul":
            self._independently_stop_iperf_client_and_server(self._stop_iperf_ue, self._stop_iperf_appserver)
        self.is_dt_running = False

    def await_finish(self):
        """
        Waits until this data transfer finish.

        :return: None
        """
        while not self.iperf_cmd.done():
            time.sleep(1)
        self.iperf_cmd.cancel()
        self.is_dt_running = False

    def get_average_throughput(self, omit=0, end=0, tput_collection_src="iperf", format=None):
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()'
        if data transfer is already finished
        or with currently available iperf intervals that were already transferred.
        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :return: value of Average throughput in unit: KBits/sec
        """
        client_ip, server_ip = self._resolve_client_and_server_ips()

        # App Server results
        appserver_iperf_results = self.iperf_cmd.current_ret['CONNECTIONS']
        if self.dt_config['version'] == 3:
            appserver_iperf_results = self._format_appserver_results(appserver_iperf_results)

        bandwidths = self._extract_bandwidths(appserver_iperf_results, client_ip, server_ip, omit, end)
        bandwidths_sum = self._calculate_bandwidths_sum(bandwidths)
        appserver_avg_tput = self._calculate_avg_tput(bandwidths_sum)
        self._print_iperf_results_in_logs(bandwidths, bandwidths_sum, avg=appserver_avg_tput, omit=omit, end=end, title="APP SERVER")

        # IPhone results
        iphone_iperf_raw_output = self.ue_pc.get_data_transfer_output(ue_id=self.iphone_name,
                                                                      data_transfer_id=self.dt_id,
                                                                      raw_output=True)['raw_output']

        iphone_iperf_results = self._parse_iphone_iperf_output_by_moler(iphone_iperf_raw_output) if self.dt_config['version'] == 2 \
            else self._parse_iphone_iperf3_output_by_moler(iphone_iperf_raw_output)

        bandwidths = self._extract_bandwidths(iphone_iperf_results, client_ip, server_ip, omit, end)
        bandwidths_sum = self._calculate_bandwidths_sum(bandwidths)
        iphone_avg_tput = self._calculate_avg_tput(bandwidths_sum)
        self._print_iperf_results_in_logs(bandwidths, bandwidths_sum, avg=iphone_avg_tput, omit=omit, end=end, title="UE IPERF")
        avg_tput = self._get_server_avg_tput(appserver_avg_tput=appserver_avg_tput, iphone_avg_tput=iphone_avg_tput)

        if format and TputFormats().valid_option(format):
            factor = TputFormats().get_multiplier(format)
        else:
            factor = TputFormats().get_default_multiplier()
        if avg_tput:
            return round(avg_tput * factor, 2)
        else:
            self.logger.debug("Couldn't get avg tput.")
            return None

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        return not self.iperf_cmd.done()

    def check_data_transfer(self):
        """Check if data transfer client and server output is progressing"""

        self.logger.debug(f'{self.name}: checking if data transfer is alive')
        iperf_interval = int(self.dt_config['interval'])
        max_time_without_output = iperf_interval * MAX_IPERF_INTERVALS_DELAY / 2
        server_iperf_output_base = self._ensure_server_received_any_data(max_time_without_output)
        validation_start_time = time.time()

        while time.time() < validation_start_time + max_time_without_output:
            time.sleep(iperf_interval)
            if not self.is_running():
                self.logger.debug(f'{self.name}: skipping check. Data transfer is already finished.')
                return

            time.sleep(iperf_interval)
            server_iperf_output_differentiate = self._get_and_parse_iperf_output_from_server()

            if len(server_iperf_output_differentiate) > len(server_iperf_output_base):
                return
        raise IperfStuckException(f"{self.name}: server didn't receive any data in {max_time_without_output}s.\n"
                                  "Please check your network connectivity between client and server.\n"
                                  "Make sure UE didn't change IP address during data transfer.\n")

    def reset_statistics(self):
        """Not Implemented"""
        raise NotImplementedError

    def get_data_transfer_statistics(self, omit: int = 0, end: int = 0, legacy_output: bool = True) -> str:
        """
        Get data transfer statistics
        :param omit: The delay in seconds to start counting the tput
                     ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: The end time in seconds to stop counting the tput
                    ex. '40' - it takes into account data till 40 second of transfer.
        :param legacy_output: Defines format of all values returned, list if legacy, string otherwise.
        :return: A string in the format "{avg_thr},{min_thr},{max_thr};{bandwidths}".
                 The bandwidths section is either a list or a stringified list,
                 depending on the value of thr_values_format ("list" or "string").
        :raises DataTransferStatisticsError: None of bandwidth rows received
        :raises DataTransferException: Invalid omit/end is given
        """
        self.logger.debug(
            f"{self.name}: Get Data Transfer Statistics with parameters: omit={omit}, end={end}"
        )
        interval = int(self.dt_config['interval'])
        omit, end = int(omit), int(end)
        omit = int(omit / interval) if omit / interval >= 1 else omit
        end = int(end / interval) if end / interval >= 1 else end

        bandwidths = self._get_bandwidths()
        self.logger.warning(f"bandwidths: {bandwidths}")
        input_bandwidths_to_bits_multiplier = 1000
        bandwidths = [bandwidth * input_bandwidths_to_bits_multiplier for bandwidth in bandwidths]
        self.logger.warning(f"bandwidths: {bandwidths}")
        if not bandwidths:
            raise DataTransferStatisticsError(
                f'{self.name}: unable to get data transfer statistics. None of the rows received'
            )
        bandwidths_sliced = bandwidths[omit:end if end else None]
        if not bandwidths_sliced:
            self.logger.debug('No rows in passed omit-end interval window')
            raise DataTransferException(
                f"{self.name}: Unable to get average throughput. Invalid omit/end is given, "
                f"rows are empty after list slicing. throughput_data_bps={bandwidths_sliced}, omit={omit}, end={end}"
            )
        self.logger.debug(
            f"{self.name}: counting average throughput "
            f"based on normalized values to bits: \n{bandwidths_sliced}"
        )
        if legacy_output:
            all_values = bandwidths_sliced
            avg_thr, min_thr, max_thr = self._statistics_from_bandwidths(all_values)
        else:
            throughput_stats, all_values = parse_data_transfer_statistics(bandwidth_list=bandwidths_sliced, logger=self.logger)
            avg_thr, min_thr, max_thr = (round(float(value), 2) for value in throughput_stats)

        self.logger.info(
            f"{self.name} data transfer statistics:\n"
            f"avg: {avg_thr} [bits/s]\n"
            f"min: {min_thr} [bits/s]\n"
            f"max: {max_thr} [bits/s]"
        )
        self.logger.info(f"RAW bits/s interval values: \n{all_values}")
        return f"{avg_thr},{min_thr},{max_thr};{all_values}"

    def get_datagram_loss(self):
        """Not Implemented"""
        raise NotImplementedError

    def list_occupied_ports_on_device(self, timeout: int = 5):
        """
        Depending on the direction of the data transfer returns ouput of netstat command run on:
         - for downlink: the UE itself
         - for uplink: the appserver
        """
        self.logger.debug(f'{self.name}: running netstat command \'netstat -an\' on UE.')
        if self.dt_config["direction"] == "dl":
            netstat_output = self.ue_pc.get_occupied_ports(ue_id=self.iphone_name)
            self.logger.debug(netstat_output)
            return netstat_output
        else:
            netstat_cmd = self.moler_device.get_cmd(cmd_name="netstat", cmd_params={'options': '-an'})
            netstat_cmd.start()
            netstat_output = netstat_cmd.await_done(timeout)

            if "INTERNET_CONNECTIONS" in netstat_output:
                internet_connections = netstat_output["INTERNET_CONNECTIONS"]
                self.logger.debug(f"netstat INTERNET_CONNECTIONS: {internet_connections}")
                return internet_connections

            self.logger.warning(f"Exceeded timeout of {timeout} sec. for netstat output. "
                                "Cannot find \"INTERNET_CONNECTIONS\" key. "
                                "\"None\" will be returned.")
            return None

    def port_for_dt(self):
        port_from_config = self.dt_config.get("port")
        if port_from_config:
            if not self._is_port_free(port_from_config):
                raise NoFreePortException(f"{self.name}: got port from robot keyword argument `port={port_from_config}`"
                                          f" but it is already in use.")
            self.logger.debug(f"{self.name}: setting port based on robot keyword argument: port={port_from_config}")
            port = port_from_config
        else:
            port = self._find_free_port()
            self.logger.debug(f"{self.name}: setting random port from {DEFAULT_PORT_MIN}-{DEFAULT_PORT_MAX} range: "
                              f"{port}")
        self.dt_config.update([("port", port)])
        return port

    def release_data_transfer(self):
        """
        Releases data transfer resources for APP server.
        There is no need to release UE resources here because it is done on taf.ue.proxy level.
        """
        if self.is_dt_running:
            self._run_action_without_raising(self._stop_iperf_appserver)
            self.logger.debug(f'{self.name}: data transfer resources force released. No need to release again')

    # private methods

    def _find_free_port(self, min_port: int = DEFAULT_PORT_MIN, max_port: int = DEFAULT_PORT_MAX,
                        attempts: int = DEFAULT_PORT_SEARCH_ATTEMPTS):
        """Get random free port on device in range (min_port:max_port]"""
        self.logger.debug(f"{self.name}: searching random free port based on netstat -an cmd output.")
        netstat_output = self.list_occupied_ports_on_device()
        free_port = FreeTcpPortFinder.find_random_free_port(
            port_validator=lambda port: FreeTcpPortFinder.is_port_free_in_netstat(netstat_output, port),
            min_port=min_port, max_port=max_port, attempts=attempts)
        self.logger.debug(f'{self!r}: chosen port {free_port}.')
        return free_port

    def _is_port_free(self, port: int):
        self.logger.debug(f"{self.name}: checking if port {port} is free based on netstat -an cmd output.")
        netstat_output = self.list_occupied_ports_on_device()
        is_port_free = FreeTcpPortFinder.is_port_free_in_netstat(netstat_output, port)
        self.logger.debug(f"{self!r}: port {port} is {self._port_status(is_port_free)}")
        return is_port_free

    @staticmethod
    def _port_status(status: bool):
        return 'free' if status is True else "already in use"

    def _resolve_client_and_server_ips(self):
        client_ip = None
        server_ip = None

        if self.dt_config["direction"] == "ul":
            client_ip = get_iphone_ip(ue_pc=self.ue_pc, ue_id=self.iphone_name, logger=self.logger, apn=self.dt_config['apn'])
            server_ip = self.dt_config['bind_interface_ip']
        elif self.dt_config["direction"] == "dl":
            client_ip = self.dt_config['bind_interface_ip']
            server_ip = get_iphone_ip(ue_pc=self.ue_pc, ue_id=self.iphone_name, logger=self.logger, apn=self.dt_config['apn'])
        return client_ip, server_ip

    def _get_server_avg_tput(self, appserver_avg_tput, iphone_avg_tput):
        avg = None
        if self.dt_config["direction"] == "ul":
            avg = appserver_avg_tput
        elif self.dt_config["direction"] == "dl":
            avg = iphone_avg_tput
        return avg

    @staticmethod
    def _remove_duplicate_and_invalid_appserver_records(iperf_results, key):  # noqa: C901
        unique_records = []
        prev_record = None
        start_time = 0.0
        end_time = start_time
        for record in iperf_results[key]:
            if record != prev_record:
                unique_records.append(record)
            prev_record = record
            end_time = max(end_time, record["Interval"][1])

        unused_rec_idx = []
        unique_bitrates_summary = set()
        for rec_idx, record in enumerate(unique_records):
            if record["Interval"] != (start_time, end_time):
                continue
            if record.get("Bitrate", None) and record["Bitrate"] == 0 or\
                    record.get("Bitrate", None) in unique_bitrates_summary:
                unused_rec_idx.append(rec_idx)
            if record.get("Bitrate", None):
                unique_bitrates_summary.add(record["Bitrate"])
        iperf_results[key] = [val for i, val in enumerate(unique_records) if i not in unused_rec_idx]

        return iperf_results[key]

    def _format_appserver_results(self, iperf_results):
        keys = list(iperf_results.keys())
        for key in keys:
            if not isinstance(iperf_results[key], list):
                continue
            self.logger.debug(iperf_results[key])
            iperf_results[key] = self._remove_duplicate_and_invalid_appserver_records(iperf_results, key)

        return iperf_results

    def _parse_iphone_iperf_output_by_moler(self, iperf_output):
        iperf = Iperf2(connection=None, options=self._build_iphone_iperf_command())
        for line in iperf_output.splitlines():
            self.logger.info(f"-------------- {line}")
            iperf.on_new_line(line, is_full_line=True)

        return iperf.current_ret['CONNECTIONS']

    @staticmethod
    def _format_iphone_iperf3_line(line, iperf, cut_last_param):
        line = line.strip()
        line = line.split(" ")
        if line[0] != "[" and "]" in line[0]:
            line = ["[ "] + line
        if "RTT" in line:
            cut_last_param = True
            line.pop()
        if "receiver" in line[-1] and iperf.client:
            return None, True
        if cut_last_param and "sender" not in line[-1]:
            line.pop()
        line = " ".join(line)
        return line, False

    def _parse_iphone_iperf3_output_by_moler(self, iperf_output):
        iperf = Iperf3(connection=None, options=self._build_iphone_iperf_command())
        cut_last_param = False
        prev_line = None
        for line in iperf_output.splitlines():
            if prev_line == line:
                continue
            prev_line = line
            line, skip = self._format_iphone_iperf3_line(line, iperf, cut_last_param)
            if skip:
                continue
            self.logger.info(f"-------------- {line}")
            iperf.on_new_line(line, is_full_line=True)

        return iperf.current_ret['CONNECTIONS']

    def _extract_bandwidths(self, iperf_results, client_ip, server_ip, omit=0, end=0):  # noqa: C901
        tput_name = "Bandwidth Raw" if self.dt_config['version'] == 2 else "Bitrate Raw"

        bandwidths = {}
        keys = list(iperf_results.keys())
        for key in keys:
            f, s = key
            if f"multiport@{client_ip}" in f and f"@{server_ip}" in s:
                pass
            elif f"@{client_ip}" in f and f"@{server_ip}" in s:
                for record in iperf_results[key]:
                    interval = record["Interval"]
                    bandwidth_raw = record[tput_name]

                    if self.check_interval(interval, omit, end):
                        if interval not in bandwidths:
                            bandwidths[interval] = [float(bandwidth_raw.split(" ")[0])]
                        else:
                            bandwidths[interval].append(float(bandwidth_raw.split(" ")[0]))
        if not bandwidths:
            raise AvgThroughputExtractionFailed("Probably iperf server didn't receive any transfer or "
                                                "parsing errors occurred.")
        return bandwidths

    @staticmethod
    def _calculate_bandwidths_sum(bandwidths):
        bandwidths_sum = {}
        for interval in bandwidths:
            interval_sum = sum(bandwidths[interval])
            bandwidths_sum[interval] = interval_sum
        return bandwidths_sum

    @staticmethod
    def _calculate_avg_tput(bandwidths_sum):
        dict_len = len(list(bandwidths_sum.values()))
        avg = int(sum(list(bandwidths_sum.values())) / dict_len)
        return avg

    @staticmethod
    def check_interval(interval, omit=0, end=0):
        begin_interval, end_interval = interval
        if omit != 0 and begin_interval < omit:
            return False
        if end != 0 and end_interval > end:
            return False
        return True

    def _print_iperf_results_in_logs(self, bandwidths, bandwidths_sum, title, avg, omit, end, line_length=54):
        tput_name = "Bandwidth" if self.dt_config['version'] == 2 else "Bitrate"

        print("\n\n" + "-" * ((line_length - len(title)) // 2), title, "-" * ((line_length - len(title)) // 2))
        intervals = list(bandwidths.keys())
        intervals.sort()

        print("{:<24}{:<15}".format('      Interval', tput_name))
        for interval in intervals:
            for bandwidth in bandwidths[interval]:
                print('{:11}-{:>5} sec   {:<15}'.format(interval[0], interval[1], str(bandwidth) + " KBits/sec"))
            if len(bandwidths[interval]) > 1:
                print('[SUM] {:>5}-{:>5} sec   {:<15}'.format(interval[0], interval[1], str(bandwidths_sum[interval]) + " KBits/sec"))
        print("-" * line_length)
        end = end if end != 0 else None
        print("Average throughput was calculated by the plugin \n"
              f"in the range [{omit}, {end}] and equals {avg} KBits/sec")
        print("-" * line_length)

    def _create_moler_device(self):
        moler_app_server_config = self._create_app_server_moler_dev_config()
        load_config(config=moler_app_server_config, config_type='dict')
        moler_device = DeviceFactory.get_device(name=self.name, initial_state="UNIX_REMOTE")
        return moler_device

    def _create_app_server_moler_dev_config(self):
        if not self.dt_config['prompt']:
            raise MandatoryParameterNotProvided("Mandatory parameter `expected_prompt` for AppServer class is not "
                                                "provided in the configuration file.")

        app_server_config = {
            'DEVICES': {
                self.name: {
                    'DEVICE_CLASS': 'moler.device.unixremote.UnixRemote',
                    'CONNECTION_HOPS': {
                        'UNIX_LOCAL': {
                            'UNIX_REMOTE': {
                                'execute_command': 'ssh',
                                'command_params': {
                                    'expected_prompt': self.dt_config['prompt'],
                                    'host': self.dt_config['host'],
                                    'login': self.dt_config['login'],
                                    'password': self.dt_config['password'],
                                    'allowed_newline_after_prompt': True}}}}},
            }}
        self.logger.debug(f"moler device (app server) configuration: {app_server_config}")
        return app_server_config

    def _build_dt_config(self, dt_definition, configuration):

        def __get_non_none(scope, options, default=None):
            """Get the first non-none value from scope otherwise return 'default'"""
            results = [scope.get(key, default) for key in options]
            return results[0] if results else None

        config_dt_iperf = configuration['data_transfer']['iperf']
        config_dt_iperf_app_server = config_dt_iperf['app_server']
        dt_definition_details = dt_definition.protocol_details

        dt_config = {
            'host': config_dt_iperf_app_server['address'],
            'password': config_dt_iperf_app_server['password'],
            'login': config_dt_iperf_app_server['user'],
            'prompt': config_dt_iperf_app_server['expected_prompt'],
            'bind_interface_ip': config_dt_iperf_app_server['bind_interface_ip'].strip(),
            'protocol': dt_definition.protocol,
            'duration': int(dt_definition.duration if dt_definition.duration != 863913600.0 else 86400.0),
            'throughput': dt_definition.throughput,
            'direction': dt_definition.direction,
            'port': dt_definition_details.get('port', None),
            'version': self._get_dt_iperf_version(dt_definition_details),
            'buffer': dt_definition_details.get('buffer', None),
            'parallel_streams': dt_definition_details.get('parallel_streams', None),
            'max_segment_size': dt_definition_details.get('max_segment_size', None),
            'packet': __get_non_none(scope=dt_definition_details, options=['packet', 'packet_size']),
            'packet_size': __get_non_none(scope=dt_definition_details, options=['packet', 'packet_size']),
            'packet_server': __get_non_none(scope=dt_definition_details, options=['packet_server', 'packet_size_server']),
            'interval': config_dt_iperf.get('interval', 1),
            'apn': dt_definition_details.get('apn', None),
            'linux_congestion': dt_definition_details.get('linux_congestion', None),
        }
        self.logger.debug(f"dt_config: {dt_config}")
        return dt_config

    def _get_dt_iperf_version(self, dt_definition_details):
        iperf_version = int(dt_definition_details.get('version', 2))
        if iperf_version not in self.supported_iperf_versions:
            raise UnsupportedIperfVersionException(iperf_version, self.supported_iperf_versions)
        return iperf_version

    def _get_app_server_iperf_version(self):
        iperf_version_cmd = self.moler_device.get_cmd(cmd_name=f"iperf{self.dt_config['version']}", cmd_params={'options': '--version'})
        iperf_version = iperf_version_cmd()['INFO'][0]
        pattern = r'[23]\.[0-9]+\.[0-9]+'
        iperf_version_number = re.search(pattern, iperf_version).group()
        self.logger.debug(f"iperf version detected on app server: {iperf_version_number}")
        return iperf_version_number

    def _add_arg_to_cmd(self, flag, value, optional=False):
        if value:
            return f"{flag} {value} "
        elif not optional:
            self.logger.debug(f'Config parameter for command "{flag}" suppose to be obligatory, but it is not set')
        return ""

    def _build_app_server_iperf_command(self):
        iperf_cmd = ""
        iphone_ip = get_iphone_ip(ue_pc=self.ue_pc, ue_id=self.iphone_name, logger=self.logger)
        if self.dt_config["direction"] == "ul":
            iperf_cmd += '-s '
            iperf_cmd = self._add_iperf_optional_options_for_server(iperf_cmd)
        elif self.dt_config["direction"] == "dl":
            iperf_cmd += self._add_arg_to_cmd(flag='-c', value=iphone_ip)
            iperf_cmd += self._add_arg_to_cmd(flag='-t', value=self.dt_config['duration'])
            if self.dt_config["protocol"] == "udp" and self.dt_config['version'] == 3:
                iperf_cmd += '-u '
            if self.dt_config["protocol"] == "udp" or self.dt_config["version"] == 3:
                iperf_cmd += "-b {}K ".format(self.dt_config["throughput"])
            iperf_cmd = self._add_iperf_optional_options_for_client(iperf_cmd)

        iperf_cmd = self._add_iperf_common_options(iperf_cmd)

        # if self.dt_config["direction"] == "ul" and iperf_version <= '2.0.12':
        #     iperf_cmd += self._add_arg_to_cmd(flag='-P', value='1')
        return iperf_cmd

    def _build_iphone_iperf_command(self):
        iperf_cmd = ""
        # call get_iphone_ip just for validation that UE has IP
        _ = get_iphone_ip(ue_pc=self.ue_pc, ue_id=self.iphone_name, logger=self.logger)
        if self.dt_config["direction"] == "ul":
            iperf_cmd += self._add_arg_to_cmd(flag='-c', value=self.dt_config['bind_interface_ip'])
            iperf_cmd += self._add_arg_to_cmd(flag='-t', value=self.dt_config['duration'])
            if self.dt_config["protocol"] == "udp" and self.dt_config['version'] == 3:
                iperf_cmd += '-u '
            if self.dt_config["protocol"] == "udp" or self.dt_config["version"] == 3:
                iperf_cmd += "-b {}K ".format(self.dt_config["throughput"])
            iperf_cmd = self._add_iperf_optional_options_for_client(iperf_cmd)
        elif self.dt_config["direction"] == "dl":
            iperf_cmd += '-s '
            iperf_cmd = self._add_iperf_optional_options_for_server(iperf_cmd)

        iperf_cmd = self._add_iperf_common_options(iperf_cmd)
        return iperf_cmd

    def _add_iperf_common_options(self, iperf_cmd):
        if self.dt_config["protocol"] == "udp" and self.dt_config['version'] == 2:
            iperf_cmd += '-u '
        elif self.dt_config["protocol"] == "tcp":
            iperf_cmd += ''

        iperf_cmd += self._add_arg_to_cmd(flag='-p', value=self.dt_config['port'])
        iperf_cmd += self._add_arg_to_cmd(flag='-i', value=self.dt_config['interval'])
        iperf_cmd += self._add_arg_to_cmd(flag='-f', value='k')

        return iperf_cmd

    def _add_iperf_optional_options_for_client(self, iperf_cmd):
        iperf_cmd += self._add_arg_to_cmd(flag='-l', value=self.dt_config['packet' or 'packet_size'], optional=True)
        iperf_cmd += self._add_arg_to_cmd(flag='-M', value=self.dt_config['max_segment_size'], optional=True)
        iperf_cmd += self._add_arg_to_cmd(flag='-P', value=self.dt_config['parallel_streams'], optional=True)
        iperf_cmd += self._add_arg_to_cmd(flag='-Z', value=self.dt_config['linux_congestion'], optional=True)
        if self.dt_config['version'] == 3:
            iperf_cmd += self._add_arg_to_cmd(flag='-w', value=self.dt_config['buffer'], optional=True)
        return iperf_cmd

    def _add_iperf_optional_options_for_server(self, iperf_cmd):
        if self.dt_config['version'] == 2:
            iperf_cmd += self._add_arg_to_cmd(flag='-w', value=self.dt_config['buffer'], optional=True)
            iperf_cmd += self._add_arg_to_cmd(flag='-l', value=self.dt_config['packet_server'], optional=True)
        return iperf_cmd

    def _verify_start_iperf_on_iphone(self):
        iphone_iperf_results = self.ue_pc.get_data_transfer_output(ue_id=self.iphone_name,
                                                                   data_transfer_id=self.dt_id,
                                                                   raw_output=True)['raw_output']
        if 'bind failed' in iphone_iperf_results:
            raise IperfStartFailed(f"iperf didn't start on iPhone ({iphone_iperf_results})")
        self.is_dt_running = True

    def _stop_iperf_ue(self):
        self.logger.debug("stopping data transfer on iphone")
        self.ue_pc.stop_data_transfer(ue_id=self.iphone_name, data_transfer_id=self.dt_id)

    def _stop_iperf_appserver(self):
        self.logger.debug("stopping data transfer on appserver")
        try:
            self.iperf_cmd.connection.send("\x1C")
            # Sometimes there is a problem with killing iperf proccess (issue occurs with old iperfs) when we use
            # Ctrl+c. That is why there is need to send Ctrl+\ (x1C) to kill iperf process in those cases.
        except CommandFailure:
            self.logger.warning("moler raised CommandFailure during breaking iperf command")
        except CommandTimeout:
            self.logger.warning("moler raised CommandTimeout during breaking iperf command")
        finally:
            self.iperf_cmd.cancel()
        self.logger.debug("stopping data transfer on appserver")

    def _independently_stop_iperf_client_and_server(self, stop_client, stop_server):
        """Try to kill iperf server and client with guaranty of calling kill on both hosts even with error on the way"""
        exc_client, tback_client = self._run_action_without_raising(stop_client)
        exc_server, tback_server = self._run_action_without_raising(stop_server)
        if exc_client and exc_server:
            raise DataTransferStopFailedTwice(exc_client, tback_client, exc_server, tback_server)
        elif exc_client or exc_server:
            raise exc_client or exc_server
        self.logger.debug(f"{self.name}: data transfer successfully stopped")

    def _parse_iperf_output(self, iperf_results, omit=0, end=0):  # Use in ensure
        self.logger.debug(f"IPERF OUTPUT: {iperf_results}")
        client_ip, server_ip = self._resolve_client_and_server_ips()
        bandwidths = self._extract_bandwidths(iperf_results, client_ip, server_ip, omit, end)
        return bandwidths

    def _ensure_server_received_any_data(self, timeout):
        """Checks if iperf did not exceed the allowed answer delay"""
        end_time = time.time() + timeout
        while time.time() < end_time:
            server_out = self._get_iperf_output_from_server()
            if len(server_out) == 0:
                self.logger.debug(f"{self.name}: There is no server out yet. Unable to check data transfer")
                time.sleep(1)
                continue
            bandwidths = self._parse_iperf_output(server_out)
            return bandwidths
        raise IperfStuckException(f"{self.name}: server didn't receive any data in {timeout}s.\n"
                                  "Please check your network connectivity between client and server.\n"
                                  "Make sure UE didn't change IP address during data transfer.\n")

    def _get_and_parse_iperf_output_from_server(self, omit=0, end=0):
        iperf_results = self._get_iperf_output_from_server()
        return self._parse_iperf_output(iperf_results, omit, end)

    def _get_iperf_output_from_server(self):  # Use in ensure
        if self.dt_config["direction"] == "ul":
            return self._format_appserver_results(self.iperf_cmd.current_ret.get('CONNECTIONS', {}))
        else:
            iphone_iperf_raw_output = self.ue_pc.get_data_transfer_output(ue_id=self.iphone_name,
                                                                          data_transfer_id=self.dt_id,
                                                                          raw_output=True)['raw_output']
            iphone_iperf_results = self._parse_iphone_iperf_output_by_moler(iphone_iperf_raw_output) \
                if self.dt_config['version'] == 2 \
                else self._parse_iphone_iperf3_output_by_moler(iphone_iperf_raw_output)
            return iphone_iperf_results

    @staticmethod
    def _run_action_without_raising(action, *args, **kwargs):
        """
        Runs action and handles an Exception if occurred
        param action: function/method to run
        :param args: action args
        :param kwargs: action kwargs
        :return: exception and traceback if calling action was not successful
        """
        try:
            action(*args, **kwargs)
            return None, None
        except Exception as e:
            return e, traceback.format_exc()

    def _get_bandwidths(self):
        iperf_results = self._get_iperf_output_from_server()
        bandwidths = self._parse_iperf_output(iperf_results)
        return [bandwidth[0] for bandwidth in bandwidths.values()]

    @staticmethod
    def _statistics_from_bandwidths(bandwidths):
        """
        Return string with dt statistics: avg,min,max;comma-delimited list of kbits/s for all intervals
        :param bandwidths: list of bandwidths values
        :return: (float, int, int) avg_tput, min_tput, max_tput
        """
        avg_tput = round(sum(bandwidths) / len(bandwidths), 2)
        min_tput = round(float(min(bandwidths)), 2)
        max_tput = round(float(max(bandwidths)), 2)
        return avg_tput, min_tput, max_tput
